import numpy as np, itertools
def read_xyz(fn):
    lines = open(fn).read().strip().split('\n')
    n=int(lines[0]); els=[]; coords=[]
    for l in lines[2:2+n]:
        p=l.split(); els.append(p[0]); coords.append([float(x) for x in p[1:4]])
    return els, np.array(coords)
for fn in ['optimized_c.xyz','optimized_c2.xyz']:
    els, X = read_xyz(fn)
    te=els.index('Te'); cl=els.index('Cl'); ss=[i for i,e in enumerate(els) if e=='S']
    d=lambda a,b: np.linalg.norm(X[a]-X[b])
    def ang(a,b,c):
        v1=X[a]-X[b]; v2=X[c]-X[b]
        return np.degrees(np.arccos(np.clip(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2),-1,1)))
    print(fn)
    print('  Te-Cl:', round(d(te,cl),3), ' Te-S:', [round(d(te,s),3) for s in ss])
    print('  angles at Te:', [round(ang(a,te,b),1) for a,b in itertools.combinations(ss+[cl],2)])
